-- Skipping an unknown `JSON` column in `RowBinaryWithNamesAndTypes` must read its value as a string
-- when `input_format_binary_read_json_as_string` is enabled.
SET input_format_binary_read_json_as_string = 1;

-- Two rows of `x JSON, arr Array(JSON), y UInt8` written with `output_format_binary_write_json_as_string = 1`.
SELECT * FROM format(RowBinaryWithNamesAndTypes, 'x JSON, arr Array(JSON), y UInt8', unhex('030178036172720179044A534F4E0B4172726179284A534F4E290555496E7438077B2261223A317D020D7B2262223A2268656C6C6F227D0B7B2263223A5B312C325D7D070D7B2262223A2268656C6C6F227D0008')) ORDER BY y;
SELECT * FROM format(RowBinaryWithNamesAndTypes, 'arr Array(JSON), y UInt8', unhex('030178036172720179044A534F4E0B4172726179284A534F4E290555496E7438077B2261223A317D020D7B2262223A2268656C6C6F227D0B7B2263223A5B312C325D7D070D7B2262223A2268656C6C6F227D0008')) ORDER BY y;
SELECT * FROM format(RowBinaryWithNamesAndTypes, 'x JSON, y UInt8', unhex('030178036172720179044A534F4E0B4172726179284A534F4E290555496E7438077B2261223A317D020D7B2262223A2268656C6C6F227D0B7B2263223A5B312C325D7D070D7B2262223A2268656C6C6F227D0008')) ORDER BY y;
SELECT * FROM format(RowBinaryWithNamesAndTypes, 'y UInt8', unhex('030178036172720179044A534F4E0B4172726179284A534F4E290555496E7438077B2261223A317D020D7B2262223A2268656C6C6F227D0B7B2263223A5B312C325D7D070D7B2262223A2268656C6C6F227D0008')) ORDER BY y;

-- One row of `d Dynamic, y UInt8` where `d` holds a `JSON` value.
SELECT * FROM format(RowBinaryWithNamesAndTypes, 'y UInt8', unhex('02016401790744796E616D69630555496E74383000800820000000077B2261223A317D07'));
